def main():
    candidates = [x for x in json.loads(INPUT.read_text()) if x["volume"] in VOLS]
    events, excluded = [], []
    reviewed_paras = set()
    for c in candidates:
        title = (c.get("titles") or [""])[0]
        cats = set(c.get("categories", []))
        keep = set()
        # Disasters are retained only when the text states a concrete occurrence.
        if "disaster" in cats:
            keep.add("disaster")
        # Social famine is distinguished from an army's supply shortage.
        if "famine" in cats and SOCIAL_FAMINE.search(c["text"]) and not (
            ARMY_ONLY_HUNGER.search(c["text"]) and not SOCIAL_FAMINE.search(c["text"])
        ):
            keep.add("famine")
        if "war" in cats:
            if COMMENTARY.search(title) or UNREALIZED.search(title) or APPOINTMENT_ONLY.search(title):
                pass
            elif WAR_ACTION.search(title):
                keep.add("war")
        if not keep:
            reason = ("仅军队断粮，不作社会饥荒事件" if "famine" in cats and
                      ARMY_ONLY_HUNGER.search(c["text"]) and not SOCIAL_FAMINE.search(c["text"])
                      else "标题/规则未指向已发生的天灾、社会饥荒或军事行动；需人工复核")
            excluded.append({"candidateId": c["id"], "reason": reason})
            continue
        # Check citation against the canonical plain text, not only the derived input.
        data = json.loads((ROOT / f"dist/volume{c['volume']}.json").read_text())
        year_obj = next(y for y in data["years"] if y["year"] == c["year"])
        para = year_obj["paragraphs"][c["anchor"]]["plain"]
        quote = c["text"]
        if quote not in para:
            excluded.append({"candidateId": c["id"], "reason": "候选引文无法在 canonical plain 中定位，待人工核查"})
            continue
        status = "reviewed" if c["id"] in READ else "provisional"
        if status == "reviewed":
            reviewed_paras.add(c["id"])
        events.append({
            "id": c["id"], "year": c["year"], "categories": sorted(keep),
            "title": title, "sources": [{"volume": c["volume"], "year": c["year"],
                "anchor": c["anchor"], "quote": quote}],
            "status": status,
            "reason": "已逐段核读上下文并核对原文" if status == "reviewed" else
                      "规则筛选候选；未完成语义与同战事跨段合并复核",
        })
