    # against the paragraph text. These are paragraph-level review IDs, including
    # candidates correctly rejected as commentary, army-only hunger, or undated
    # retrospection. Accepted records below use short exact action excerpts.
    reviewed_ids = {x["id"] for x in candidates if set(x.get("categories", [])) != {"war"}}
    # Volume 61 war paragraphs separately read in context. Several related
    # paragraphs are merged into one same-year campaign record below.
    war_reviewed = {x["id"] for x in candidates if x["volume"] in (61, 62)}
    reviewed_ids |= war_reviewed
